"""Editorial Grade 10 topic packs, grounded in the supplied DLS papers.
Source questions remain in their original PDFs so no equation or diagram is lost.
All practice questions and learning notes below are newly authored.
"""
topics=[]
def add(subject,title,group,source,notes,formula,practice,visual='flow',tip='Show your reasoning and check the units or restrictions in your final answer.'):
 refs=[]
 for item in source:
  paper,page,label,*memo_page=item
  refs.append(dict(paper=str(paper),page=page,label=label,memoPage=memo_page[0] if memo_page else None))
 topics.append(dict(subject=subject,title=title,group=group,sources=refs,notes=notes,formula=formula,practice=[dict(question=q,answer=a) for q,a in practice],visual=visual,tip=tip))

add('maths','Numbers, surds & intervals','Paper 1',[(1,3,'Question 1: number representation'),(2,2,'Question 1(a): types of numbers',2)],
 [('What makes a number rational?','A rational number is a ratio of integers with a non-zero denominator. Its decimal expansion terminates or repeats. An irrational number has a non-terminating, non-repeating decimal.'),('How do you simplify a surd?','Take square factors outside the root: √72 = √(36 × 2) = 6√2. Add only like surds, such as 3√2 + 2√2 = 5√2.'),('What do interval brackets mean?','A square bracket includes an endpoint; a round bracket excludes it. Infinity always takes a round bracket. For example, −2 < x ≤ 5 is (−2; 5].')],
 '√(a²b) = |a|√b  •  b ≥ 0',[
 ('Simplify √50 + √8.','√50 = 5√2 and √8 = 2√2. Add like surds: 5√2 + 2√2 = 7√2.'),('Write −3 ≤ x < 4 in interval notation. Is √7 rational?','The interval is [−3; 4). Since 7 is not a perfect square, √7 is irrational. It lies between 2 and 3 because 4 < 7 < 9.')], 'numberline')
add('maths','Algebra & equations','Paper 1',[(1,4,'Question 2: solve equations'),(1,9,'Question 6: factorisation'),(6,2,'Question 1: algebraic simplification',2)],
 [('Why factorise first?','Look for a common factor, difference of squares, or a trinomial. Factoring reveals zeros and can simplify fractions. Cancel factors, never separate terms across a sum.'),('How do you solve a quadratic?','Move everything to one side, factorise and use the zero-product rule. If ab = 0, then a = 0 or b = 0. Check each root in the original equation.'),('What restrictions matter?','A denominator cannot equal zero. Multiplying by an expression containing x can create invalid solutions, so record excluded values before simplifying.')],
 'a² − b² = (a − b)(a + b)',[
 ('Solve x² − 5x + 6 = 0.','Find two numbers with product 6 and sum −5: −2 and −3. (x − 2)(x − 3) = 0, so x = 2 or x = 3.'),('Simplify (x² − 9)/(x² + 3x), including restrictions.','Factorise: (x − 3)(x + 3)/[x(x + 3)] = (x − 3)/x. The original denominator excludes x = 0 and x = −3.')])
add('maths','Exponents & number patterns','Paper 1',[(1,8,'Question 5: linear sequences'),(1,9,'Question 6(c): exponent laws'),(6,2,'Question 1.1: exponent laws',2)],
 [('How do exponent laws work?','Multiply powers of the same base by adding exponents; divide by subtracting exponents. A power raised to another power multiplies exponents. A negative exponent indicates a reciprocal.'),('How do you recognise an arithmetic sequence?','Successive terms have a constant difference d. Subtract each term from the next to find d. The first term is a.'),('How do you find a term position?','Use Tₙ = a + (n − 1)d, substitute the target term and solve for n. A valid position must be a positive integer.')],
 'Tₙ = a + (n − 1)d  •  aᵐaⁿ = aᵐ⁺ⁿ',[
 ('For 5, 9, 13, … find Tₙ and T₂₀.','a = 5 and d = 4. Tₙ = 5 + 4(n − 1) = 4n + 1. T₂₀ = 81.'),('Simplify (2³ × 2⁻¹)/2².','Use the common base 2: 2^(3 − 1 − 2) = 2⁰ = 1.')], 'sequence')
add('maths','Functions & transformations','Paper 1',[(1,6,'Question 4: sketch functions'),(1,10,'Question 7: function features')],
 [('Which features belong on a graph?','Label the axes, intercepts, turning point for a parabola and asymptotes for a hyperbola. Use the equation to calculate features rather than estimating them.'),('How do vertical transformations work?','Adding q to f(x) shifts a graph up by q. Multiplying the entire function by −1 reflects it in the x-axis. These changes affect y-values.'),('What are domain and range?','Domain means allowed inputs x; range means possible outputs y. For y = a/x + q, x ≠ 0 and y ≠ q. For y = x² + q, the range is y ≥ q.')],
 'y = ax² + q  •  y = a/x + q',[
 ('State the turning point and range of y = 2x² − 3.','The turning point is (0; −3). The parabola opens upwards because a = 2 > 0. Therefore the range is y ≥ −3.'),('Reflect f(x) = 3/x + 2 in the x-axis, then move it down 1.','Reflection gives −f(x) = −3/x − 2. Moving down 1 gives y = −3/x − 3. Its asymptotes are x = 0 and y = −3.')], 'parabola')
add('maths','Financial maths','Paper 1',[(1,12,'Question 8: interest growth'),(11,6,'Question 4: simple interest and inflation')],
 [('How does simple interest grow?','Simple interest is calculated on the original principal only. It adds the same monetary amount each year at a fixed rate.'),('How does compound interest grow?','Compound interest is calculated on the updated balance. Interest earns further interest, producing exponential growth. Convert a percentage to a decimal before substitution.'),('What do the symbols mean?','P is the original amount; A is the final amount; i is the rate per period as a decimal; n is the number of matching periods. Keep intermediate values unrounded.')],
 'Simple: A = P(1 + in)  •  Compound: A = P(1 + i)ⁿ',[
 ('R2 000 earns 6% simple interest yearly for 3 years. Find the balance.','A = 2 000(1 + 0.06 × 3) = 2 000 × 1.18 = R2 360.00. Interest earned is R360.00.'),('R2 000 earns 6% compound interest yearly for 3 years. Find the balance.','A = 2 000(1.06)³ = R2 382.03 to the nearest cent. This exceeds simple interest because interest is earned on earlier interest.')], 'growth', 'Use the rate and period stated in the question. This is school mathematics, not an investment recommendation.')
add('maths','Probability & Venn diagrams','Paper 1',[(1,13,'Question 9: sibling survey',2),(6,10,'Question 5.2: probability',10)],
 [('What goes in a Venn overlap?','The overlap contains outcomes in both A and B. Place the overlap first, then subtract it from each set total to get the exclusive regions.'),('How do you calculate a union?','Add P(A) and P(B), then subtract their overlap once to avoid double counting. The outside region is 1 − P(A ∪ B).'),('What are complementary events?','A and its complement cover all outcomes and cannot occur together. Their probabilities sum to 1. Mutually exclusive events have no overlap.')],
 'P(A ∪ B) = P(A) + P(B) − P(A ∩ B)',[
 ('Of 60 learners, 32 play football, 25 swim, and 12 do both. How many do neither?','Football only = 32 − 12 = 20; swimming only = 25 − 12 = 13. At least one = 20 + 12 + 13 = 45. Neither = 60 − 45 = 15.'),('P(A) = 0.4, P(B) = 0.35 and P(A ∩ B) = 0.1. Find P(A ∪ B).','P(A ∪ B) = 0.4 + 0.35 − 0.1 = 0.65. The probability of neither is 1 − 0.65 = 0.35.')], 'venn')
add('maths','Trigonometry & trig graphs','Paper 2',[(17,4,'Question 2: right-triangle ratios',4),(17,7,'Question 4: angles of depression',7),(17,8,'Question 5: trig graphs',8)],
 [('How do you choose a trig ratio?','Relative to the chosen angle, label opposite, adjacent and hypotenuse. Use sine for opposite/hypotenuse, cosine for adjacent/hypotenuse and tangent for opposite/adjacent.'),('How do trig graphs repeat?','Sine and cosine repeat every 360°; tangent every 180°. For a sin(x) or a cos(x), amplitude is |a|. A vertical shift changes the midline, not the amplitude.'),('How do angles of depression work?','The angle from a horizontal line down to an object equals the angle of elevation from the object when the horizontal lines are parallel. Draw the triangle first.')],
 'sin θ = O/H  •  cos θ = A/H  •  tan θ = O/A',[
 ('A ladder is 10 m long and makes 60° with the ground. Find its vertical height.','The ladder is the hypotenuse. h = 10 sin 60° = 5√3 ≈ 8.66 m.'),('State the amplitude, period and range of y = 3 sin x + 1.','Amplitude = 3; period = 360°. The midline is y = 1 and the output extends 3 above and below it, so −2 ≤ y ≤ 4.')], 'wave')
add('maths','Analytical geometry','Paper 2',[(17,10,'Question 6: coordinates and triangles',10)],
 [('How do you find distance and midpoint?','Distance comes from Pythagoras using coordinate differences. Midpoint is the average of each coordinate. Keep exact square roots until the final answer.'),('How do gradients describe lines?','Gradient is change in y divided by change in x. Parallel non-vertical lines have equal gradients; perpendicular non-vertical lines have gradients with product −1.'),('How can you prove a shape analytically?','Use distances to prove equal sides, gradients to prove parallel or perpendicular sides, and midpoints to prove diagonals bisect each other. State the geometric conclusion.')],
 'm = (y₂ − y₁)/(x₂ − x₁)  •  d² = Δx² + Δy²',[
 ('Find the midpoint and length of AB, where A(−2; 1) and B(4; 9).','Midpoint = ((−2 + 4)/2; (1 + 9)/2) = (1; 5). Length = √(6² + 8²) = √100 = 10 units.'),('Find the equation through (2; 3) with gradient −2.','Use y − 3 = −2(x − 2). Expand: y − 3 = −2x + 4, hence y = −2x + 7.')], 'triangle')
add('maths','Euclidean geometry & measurement','Paper 2',[(17,6,'Question 3: midpoint theorem',6),(17,14,'Question 7: volume and area',14),(17,18,'Question 10: geometric proofs',18)],
 [('What does the midpoint theorem say?','The segment joining the midpoints of two sides of a triangle is parallel to the third side and half its length. Both midpoint conditions must be established.'),('How do you prove a parallelogram?','Show both pairs of opposite sides parallel, both pairs equal, one opposite pair equal and parallel, or diagonals bisecting each other. Give a reason for every proof step.'),('How do you handle composite solids?','Split the object into known shapes and add or subtract their volumes. For surface area, include only exposed surfaces and identify whether a cone base is included.')],
 'Vcone = ⅓πr²h  •  Vsphere = ⁴⁄₃πr³  •  Atriangle = ½bh',[
 ('Two sides of a triangle have midpoints M and N. The third side is 18 cm. Find MN.','By the midpoint theorem, MN is parallel to the third side and half its length. MN = 18/2 = 9 cm.'),('A cone has radius 3 cm and height 8 cm. Find its volume.','V = ⅓πr²h = ⅓π × 9 × 8 = 24π ≈ 75.40 cm³. The radius, not diameter, must be used.')], 'triangle')
add('maths','Statistics & data handling','Paper 2',[(17,16,'Question 8: box plots',16),(17,17,'Question 9: grouped frequencies',17),(9,2,'Question 1: class marks',2)],
 [('What do centre and spread tell you?','Mean is total divided by count; median is the middle of sorted data; mode is the most frequent value. Range is maximum minus minimum. IQR = Q₃ − Q₁ describes the middle 50%.'),('How do you estimate a grouped mean?','Multiply each class midpoint by its frequency, add the products and divide by the total frequency. It is an estimate because actual individual values are unknown.'),('How do you interpret a box plot?','The five-number summary is minimum, Q₁, median, Q₃ and maximum. Compare median for typical performance and IQR for consistency. A small IQR means less spread.')],
 'Estimated mean = Σ(f × midpoint)/Σf',[
 ('Find the mean, median and range of 2, 4, 4, 6, 9.','Mean = 25/5 = 5. The middle sorted value is 4, so median = 4. Range = 9 − 2 = 7.'),('A grouped table has midpoints 5 and 15 with frequencies 3 and 7. Estimate the mean.','Σfx = 5 × 3 + 15 × 7 = 120. Σf = 10. Estimated mean = 120/10 = 12.')], 'bars')

add('ap','Advanced algebra & binomial expansion','Algebra',[(39,11,'Question 7: algebraic expansion',11),(41,6,'Question 3: algebra',6)],
 [('How does the binomial pattern work?','In (a + b)ⁿ the powers of a decrease while the powers of b increase. Coefficients come from Pascal’s triangle or combinations. Every term has total degree n.'),('How do you compare coefficients?','Expand and collect like powers, then equate coefficients of matching powers on the two sides. An identity must hold for every permitted x.'),('How do you simplify compound fractions?','Factor every numerator and denominator, find a common denominator inside the fraction, then multiply by the reciprocal of the divisor. Record all original restrictions.')],
 '(a + b)³ = a³ + 3a²b + 3ab² + b³',[
 ('Expand (x + 2)³.','Use coefficients 1, 3, 3, 1: x³ + 3x²(2) + 3x(2²) + 2³ = x³ + 6x² + 12x + 8.'),('If (x + a)² = x² + 10x + b for all x, find a and b.','Expansion gives x² + 2ax + a². Comparing coefficients: 2a = 10, so a = 5. Then b = a² = 25.')], 'sequence')
add('ap','Polynomials & nature of roots','Algebra',[(39,14,'Question 8: factorisation and roots',14),(39,16,'Question 9: discriminants',16),(41,5,'Question 2(c): nature of quadratic roots',5)],
 [('What does the factor theorem say?','If f(k) = 0, then (x − k) is a factor of polynomial f(x). After finding a factor, divide to reduce the degree and solve the remaining polynomial.'),('How does the discriminant classify roots?','For ax² + bx + c = 0, Δ = b² − 4ac. Positive Δ gives two distinct real roots; zero gives equal real roots; negative Δ gives non-real roots.'),('How do parameter questions work?','Write the appropriate discriminant inequality, substitute coefficients and solve for the parameter. Check that the leading coefficient is non-zero before using quadratic rules.')],
 'Δ = b² − 4ac  •  x = (−b ± √Δ)/(2a)',[
 ('Classify the roots of x² + 4x + 7 = 0.','Δ = 4² − 4(1)(7) = −12. Since Δ < 0, the roots are non-real (a complex conjugate pair).'),('Show x − 2 is a factor of x³ − 3x² − 4x + 12 and solve the equation.','f(2) = 8 − 12 − 8 + 12 = 0. Factorisation gives (x − 2)(x² − x − 6) = (x − 2)(x − 3)(x + 2). Roots: 2, 3 and −2.')], 'parabola')
add('ap','Functions, modulus & area estimates','Functions',[(39,18,'Question 10: function graph',18),(39,19,'Question 11: left-endpoint approximation',19),(41,8,'Question 4(c): modulus transformation',8),(41,9,'Question 5: endpoint approximation',9)],
 [('How does absolute value work?','|u| is the distance of u from zero, so it is never negative. |x − h| + k has a V-shaped graph with vertex (h; k). Solve modulus equations by considering both signs.'),('What is an endpoint approximation?','Split an interval into equal widths Δx. At each left endpoint calculate a rectangle height f(x). Add height × width for all rectangles. This estimates signed area.'),('How can you judge the estimate?','For an increasing positive function, left rectangles underestimate the area. Smaller partitions usually improve accuracy. Include a sketch and the interval limits.')],
 'Left sum = Δx[f(x₀) + … + f(xₙ₋₁)]',[
 ('Solve |x − 3| = 5 and state the vertex of y = |x − 3|.','x − 3 = 5 or x − 3 = −5, so x = 8 or x = −2. The graph vertex is (3; 0).'),('Use left rectangles of width 1 to estimate the area under y = x² from x = 0 to 3.','Left endpoints are 0, 1 and 2. Sum = 1(0² + 1² + 2²) = 5 square units. Since x² increases on this interval, this is an underestimate.')], 'bars')
add('ap','Conditional probability & tree diagrams','Probability',[(41,12,'Question 6: airport screening tree',12),(39,3,'Question 1: contingency table',3)],
 [('What changes with conditional probability?','Given B restricts the sample space to B. Divide the probability of both A and B by the probability of B, provided P(B) > 0.'),('How do you use a tree diagram?','Branch probabilities leaving one node sum to 1. Multiply along a path for a joint probability. Add disjoint paths to obtain the total probability of an event.'),('Why is a positive test not certainty?','A positive result can come from a true positive or a false positive. The prior probability matters, so use all positive paths in the denominator.')],
 'P(A | B) = P(A ∩ B)/P(B)',[
 ('10% of bags contain an item. A scanner detects 90% of these and flags 5% of other bags. Find P(flag).','P(flag) = 0.10 × 0.90 + 0.90 × 0.05 = 0.09 + 0.045 = 0.135, or 13.5%.'),('Using the same scanner data, find P(item | flag).','P(item and flag) = 0.09. P(flag) = 0.135. Therefore P(item | flag) = 0.09/0.135 = 2/3 ≈ 66.7%.')], 'tree')
add('ap','Counting & permutations','Probability',[(41,14,'Question 8: codes and seating',14)],
 [('When do you multiply choices?','For a sequence of decisions, multiply the number of available choices at each step. State whether repetition is allowed, and whether order matters.'),('What is a factorial?','n! counts arrangements of n distinct objects: n(n − 1)…1. If a position is fixed, arrange only the objects left over. Treat a required adjacent pair as a block.'),('How do restrictions affect seating?','Place the most restricted group first, then count the remaining choices. For alternating groups, identify valid patterns before arranging people in each group.')],
 'n! = n(n − 1)…1  •  0! = 1',[
 ('How many three-digit PINs use digits 0–5 if repetition is allowed?','Each of the three positions has 6 choices, including an initial zero because this is a PIN. Total = 6³ = 216.'),('Five different pupils sit in a row. Two named pupils must occupy the first two seats in either order. How many arrangements?','The two named pupils have 2! orders. The remaining three have 3! orders. Total = 2! × 3! = 2 × 6 = 12.')], 'tree')
add('ap','Independence & multi-way data','Probability',[(41,13,'Question 7: independent events',13),(41,16,'Question 9: employee data',16)],
 [('What does independence mean?','Knowing one event occurred does not change the probability of the other. Test P(A ∩ B) = P(A)P(B), or compare conditional and unconditional probabilities.'),('How do tables give probabilities?','For an unconditional probability divide the requested cell or total by the grand total. For a conditional probability divide by the total of the group named after given.'),('Are independent events mutually exclusive?','These are different ideas. Mutually exclusive events cannot happen together. Two events with positive probabilities cannot be both mutually exclusive and independent.')],
 'Independent: P(A ∩ B) = P(A)P(B)',[
 ('P(A) = 0.4, P(B) = 0.5 and P(A ∩ B) = 0.2. Are A and B independent?','P(A)P(B) = 0.4 × 0.5 = 0.2, equal to P(A ∩ B). Therefore the events are independent.'),('A class has 12 swimmers, 8 of whom cycle. Among the other 18 learners, 6 cycle. Find P(cycle | swimmer).','Restrict the denominator to the 12 swimmers. P(cycle | swimmer) = 8/12 = 2/3. The 6 other cyclists do not belong in this conditional numerator.')], 'venn')

add('ap','Complex numbers & the Argand plane','Algebra',[(39,10,'Question 6: complex product, modulus and argument',10),(41,7,'Question 4: complex division and coefficients',7)],
 [('What is a complex number?','A complex number has the form a + bi where a and b are real and i² = −1. On an Argand diagram, the horizontal axis is the real part and the vertical axis is the imaginary part.'),('How do conjugates help division?','The conjugate of a + bi is a − bi. Multiply the numerator and denominator by the denominator’s conjugate. Their product a² + b² is real, making division easier.'),('How do modulus and argument work?','The modulus is the distance from the origin: |a + bi| = √(a² + b²). The argument is the angle from the positive real axis. Use the quadrant to choose the correct angle, not just the inverse-tangent value.')],
 'i² = −1  •  |a + bi| = √(a² + b²)',[
 ('Simplify (2 + 3i)(1 − 2i).','Expand: 2 − 4i + 3i − 6i². Since i² = −1, this equals 2 − i + 6 = 8 − i.'),('Write (3 + i)/(1 − i) in the form a + bi.','Multiply top and bottom by 1 + i: [(3 + i)(1 + i)]/[(1 − i)(1 + i)] = (2 + 4i)/2 = 1 + 2i.')], 'complex')
add('ap','Standard deviation & statistical intervals','Statistics',[(39,8,'Question 5: one and two standard-deviation intervals',8)],
 [('What does standard deviation measure?','Standard deviation measures spread around the mean in the same units as the data. A smaller standard deviation indicates values are more closely clustered around the mean.'),('How do symmetric intervals work?','An interval within one standard deviation has endpoints μ − σ and μ + σ. The mean is the midpoint of the interval and σ is its half-width. For two standard deviations the half-width is 2σ.'),('When can percentage rules be used?','The familiar approximate 68%, 95%, 99.7% rule describes normally distributed data. Do not apply it to every data set without an assumption about its distribution.')],
 'One σ: [μ − σ; μ + σ]  •  Two σ: [μ − 2σ; μ + 2σ]',[
 ('The interval within one standard deviation of the mean is [12; 20]. Find μ and σ.','The mean is the midpoint: μ = (12 + 20)/2 = 16. Half the width is σ = (20 − 12)/2 = 4.'),('A set has μ = 50 and σ = 6. State the interval within two standard deviations.','Two standard deviations = 2 × 6 = 12. The interval is [50 − 12; 50 + 12] = [38; 62]. No percentage claim follows unless a distribution is specified.')], 'distribution')

add('physical','Waves, sound & superposition','Physics',[(35,6,'Question 2: wave properties',2),(31,5,'Question 2.1: sound waves',2)],
 [('What do amplitude and wavelength measure?','Amplitude is maximum displacement from equilibrium. Wavelength is the distance between nearest points in phase, such as consecutive crests. Frequency counts complete oscillations per second.'),('How does superposition work?','When pulses overlap, their displacements add algebraically. Same-side pulses reinforce; opposite-side pulses partially or fully cancel. After passing, ideal pulses continue with their original shape.'),('What controls pitch and loudness?','A higher frequency produces a higher pitch. Greater amplitude generally means louder sound. Sound is a longitudinal mechanical wave and requires a medium.')],
 'v = fλ  •  T = 1/f',[
 ('A wave has frequency 5 Hz and wavelength 0.8 m. Find speed and period.','v = fλ = 5 × 0.8 = 4 m/s. T = 1/f = 1/5 = 0.2 s.'),('A +4 cm pulse overlaps a −1.5 cm pulse. What is the resultant displacement at the overlap?','Add signed displacements: 4 + (−1.5) = +2.5 cm. This is partial destructive interference.')], 'wave')
add('physical','Electromagnetic radiation','Physics',[(35,8,'Question 3: spectrum and photons',4)],
 [('How are EM waves different?','Electromagnetic waves consist of changing electric and magnetic fields. They can travel through a vacuum at c ≈ 3.0 × 10⁸ m/s and are transverse.'),('How is the spectrum ordered?','From low to high frequency: radio, microwave, infrared, visible, ultraviolet, X-rays, gamma rays. Wavelength decreases as frequency increases.'),('What is a photon?','A photon is a quantum of electromagnetic radiation with energy E = hf. Higher frequency means more energy per photon; a larger wave amplitude is a different property.')],
 'c = fλ  •  E = hf  •  h = 6.63 × 10⁻³⁴ J·s',[
 ('Find the frequency of radiation with wavelength 6.0 × 10⁻⁷ m in vacuum.','f = c/λ = (3.0 × 10⁸)/(6.0 × 10⁻⁷) = 5.0 × 10¹⁴ Hz.'),('Find the energy of a photon with frequency 5.0 × 10¹⁴ Hz.','E = hf = (6.63 × 10⁻³⁴)(5.0 × 10¹⁴) = 3.315 × 10⁻¹⁹ J ≈ 3.32 × 10⁻¹⁹ J.')], 'wave', 'Convert nm to metres before substitution. The supplied 2024 paper calls 7.8 nm visible light; that wavelength is outside the visible spectrum.')
add('physical','Magnetism & electrostatics','Physics',[(35,9,'Question 4: fields and charge investigation',5),(35,3,'Questions 1.3–1.5: charge and magnets',1)],
 [('What does a field show?','A magnetic field describes the region where magnetic forces can act. Outside a bar magnet field lines run north to south; closer lines indicate a stronger field. Electric current produces a magnetic field.'),('How is charge transferred?','Electrons move between objects; protons remain bound in nuclei in ordinary charging. Like charges repel and unlike charges attract. Total charge is conserved.'),('How do you interpret a charge experiment?','Identify the changed variable, the measured variable and what is held constant. A neutral conductor can be attracted to a charged object by redistribution of charge without gaining net charge.')],
 '|Q| = n e  •  e = 1.60 × 10⁻¹⁹ C',[
 ('An object has charge −4.8 × 10⁻¹⁹ C. How many excess electrons are present?','n = |Q|/e = (4.8 × 10⁻¹⁹)/(1.6 × 10⁻¹⁹) = 3. The negative sign means three excess electrons.'),('Two identical metal spheres with +6 nC and −2 nC touch, then separate. Find the final charge on each.','Total charge = +6 − 2 = +4 nC. Identical spheres share it equally, giving +2 nC each. Charge is conserved.')], 'charges')
add('physical','Electric circuits','Physics',[(35,12,'Question 5: circuit and Ohm’s law',6)],
 [('What are current, voltage and resistance?','Current is charge flow per unit time. Potential difference is energy transferred per unit charge. Resistance is the ratio V/I for a component at the stated operating conditions.'),('How do series circuits combine?','Current is the same through series components. Resistances add and the supply voltage is shared. An ammeter is connected in series.'),('How do parallel circuits combine?','Parallel branches share the same potential difference. Branch currents add at a junction. For resistors, reciprocals of resistance add. A voltmeter is connected across a component.')],
 'V = IR  •  Q = It  •  1/Rparallel = 1/R₁ + 1/R₂',[
 ('A 12 V battery is connected across a 6 Ω resistor. Find the current and charge passing in 30 s.','I = V/R = 12/6 = 2 A. Q = It = 2 × 30 = 60 C.'),('Find the total resistance of 6 Ω and 3 Ω connected in parallel.','1/R = 1/6 + 1/3 = 3/6 = 1/2, so R = 2 Ω. It is smaller than either individual resistance.')], 'circuit')
add('physical','Vectors & motion graphs','Physics',[(35,14,'Question 6: resultant and equilibrant',7),(35,15,'Question 7: velocity-time graph',8)],
 [('What makes a quantity a vector?','A vector has both magnitude and direction. Displacement, velocity and force are vectors; distance, speed and energy are scalars. Choose a positive direction before calculating.'),('How do you add perpendicular vectors?','Draw a head-to-tail diagram. Use Pythagoras for the resultant magnitude and trigonometry for its direction. The equilibrant has equal magnitude and opposite direction.'),('How do you read motion graphs?','Gradient of displacement-time gives velocity. Gradient of velocity-time gives acceleration. Signed area under velocity-time gives displacement; add absolute areas for distance.')],
 'a = Δv/Δt  •  vaverage = displacement/time',[
 ('Forces of 6 N east and 8 N north act together. Find the resultant.','Magnitude = √(6² + 8²) = 10 N. Direction θ = tan⁻¹(8/6) = 53.13° north of east.'),('A velocity-time graph rises uniformly from 0 to 12 m/s in 4 s. Find acceleration and displacement.','a = (12 − 0)/4 = 3 m/s². Displacement is the triangular area: ½ × 4 × 12 = 24 m in the positive direction.')], 'motion')
add('physical','Energy & conservation','Physics',[(35,18,'Question 8: mechanical energy',9)],
 [('Where is mechanical energy stored?','Kinetic energy is associated with motion. Gravitational potential energy depends on mass, field strength and height relative to a chosen reference level.'),('When is mechanical energy conserved?','If only conservative forces do work, total kinetic plus potential energy stays constant. With friction, mechanical energy can become thermal energy, while total energy is still conserved.'),('How does speed affect kinetic energy?','Kinetic energy depends on speed squared. Doubling speed at constant mass quadruples kinetic energy. Always convert grams to kilograms and use metres and seconds.')],
 'Eₖ = ½mv²  •  Eₚ = mgh  •  g = 9.8 m/s²',[
 ('A 2 kg object moves at 3 m/s. Find its kinetic energy.','Eₖ = ½ × 2 × 3² = 9 J.'),('An object falls from rest through 5 m with no air resistance. Find its speed just before reaching the bottom.','mgh = ½mv², so v = √(2gh) = √(2 × 9.8 × 5) = √98 ≈ 9.90 m/s downward.')], 'energy')
add('physical','Atomic structure & periodicity','Chemistry',[(33,4,'Question 2: isotopes and atomic structure',1),(37,6,'Question 2: atomic structure')],
 [('How do you count particles?','Atomic number Z counts protons; mass number A counts protons plus neutrons. A neutral atom has Z electrons. Ions form when electrons are lost or gained.'),('What are isotopes?','Isotopes are atoms of the same element with different neutron counts. They have the same Z but different A. Relative atomic mass is a weighted mean of isotope masses.'),('How does the periodic table help?','For main-group elements, similar valence-electron arrangements produce similar chemical properties. Across a period, valence patterns change systematically.')],
 'neutrons = A − Z  •  Ar = Σ(isotope mass × fraction)',[
 ('A neutral atom has Z = 12 and A = 24. State its proton, neutron and electron numbers.','Protons = 12; neutrons = 24 − 12 = 12; electrons = 12. Its 2+ ion would have 10 electrons.'),('An element has 75% isotope of mass 35 and 25% isotope of mass 37. Find the weighted atomic mass.','Ar = 0.75 × 35 + 0.25 × 37 = 26.25 + 9.25 = 35.5.')], 'atom')
add('physical','Bonding & chemical formulae','Chemistry',[(37,8,'Question 3: bonding and formulae'),(33,7,'Question 5: electronegativity and bonding',4)],
 [('How do ionic and covalent bonds differ?','Ionic bonding is electrostatic attraction between oppositely charged ions after electron transfer. Covalent bonding involves shared electron pairs between atoms.'),('How do you write an ionic formula?','Balance positive and negative charges to make an electrically neutral formula unit. Reduce to the lowest whole-number ratio. Use brackets for repeated polyatomic ions.'),('What does a Lewis diagram show?','Show valence electrons as dots or crosses, paired bonding electrons and lone pairs. Distinguish molecules from ionic lattices; a solid ionic compound is not made of separate molecules.')],
 'Total positive charge + total negative charge = 0',[
 ('Write the formula for the compound formed by Mg²⁺ and Cl⁻.','One Mg²⁺ requires two Cl⁻ ions to balance charge: MgCl₂. The net charge is +2 + 2(−1) = 0.'),('How many bonding pairs and lone pairs are around oxygen in H₂O?','Oxygen has 6 valence electrons. It shares one pair with each of two hydrogens, giving 2 bonding pairs and leaving 2 lone pairs on oxygen.')], 'atom')
add('physical','Chemical reactions & redox','Chemistry',[(37,11,'Question 4: equations and redox'),(33,6,'Question 3: reaction investigation',2)],
 [('Why must equations be balanced?','Atoms and total charge are conserved. Change coefficients in front of formulae, never subscripts inside a chemical formula. Check every element after balancing.'),('How do you recognise redox?','Oxidation is loss of electrons and an increase in oxidation number. Reduction is gain of electrons and a decrease in oxidation number. They happen together.'),('What are spectator ions?','Spectator ions remain chemically unchanged in an aqueous reaction. Remove identical ions on both sides to write the net ionic equation, preserving charge and atom balance.')],
 'OIL RIG: Oxidation Is Loss; Reduction Is Gain',[
 ('Balance: Mg + O₂ → MgO.','Use 2 oxygen atoms on the product side, then balance magnesium: 2Mg + O₂ → 2MgO.'),('For Zn + Cu²⁺ → Zn²⁺ + Cu, identify oxidation and reduction.','Zn → Zn²⁺ + 2e⁻ is oxidation. Cu²⁺ + 2e⁻ → Cu is reduction. Zinc is the reducing agent because it donates electrons.')], 'flow')
add('physical','Energy changes & catalysts','Chemistry',[(37,12,'Question 5: reaction energy profile')],
 [('What does enthalpy change mean?','ΔH = energy of products − energy of reactants. Negative ΔH indicates an exothermic reaction; positive ΔH indicates endothermic. Label axes on an energy profile.'),('What is activation energy?','Activation energy is the energy barrier from reactants to the transition state. Bond breaking absorbs energy; bond formation releases energy.'),('How does a catalyst work?','A catalyst provides an alternative pathway with a lower activation energy. It speeds up a reaction without being used up overall and does not change ΔH or the reactant/product energy levels.')],
 'ΔH = Hproducts − Hreactants',[
 ('Reactants have energy 80 kJ and products 30 kJ. Find ΔH and classify the reaction.','ΔH = 30 − 80 = −50 kJ. The reaction is exothermic because products are lower in energy and energy is released.'),('Reactants are at 40 kJ/mol and the peak at 150 kJ/mol. A catalyst lowers the peak to 100. Find both activation energies.','Uncatalysed Eₐ = 150 − 40 = 110 kJ/mol. Catalysed Eₐ = 100 − 40 = 60 kJ/mol. ΔH is unchanged.')], 'energy')
add('physical','Acids, bases & conjugate pairs','Chemistry',[(37,14,'Question 6: acid-base reactions'),(33,7,'Question 4: acids and indicators',3)],
 [('What is a Brønsted–Lowry acid?','An acid donates a proton (H⁺); a base accepts a proton. This definition describes proton transfer in a reaction, so identify which reactant actually donates or accepts.'),('How do conjugate pairs differ?','An acid and its conjugate base differ by one H⁺. Removing H⁺ lowers the charge by 1; adding H⁺ raises the charge by 1. Water can act as an acid or a base.'),('What happens when acid meets carbonate?','An acid and a carbonate or hydrogen carbonate produce a salt, water and carbon dioxide. CO₂ turns clear limewater milky. Balance the complete reaction.')],
 'Acid + base ⇌ conjugate base + conjugate acid',[
 ('In HCl + H₂O → H₃O⁺ + Cl⁻ identify the acid, base and conjugate pairs.','HCl donates H⁺, so is the acid. H₂O accepts it, so is the base. Conjugate pairs are HCl/Cl⁻ and H₂O/H₃O⁺.'),('Balance the reaction between hydrochloric acid and sodium carbonate.','2HCl + Na₂CO₃ → 2NaCl + H₂O + CO₂. The gas can be identified by turning clear limewater milky.')], 'flow')
add('physical','Moles & stoichiometry','Chemistry',[(37,16,'Question 7: concentration and moles'),(37,17,'Question 7: hydrates and mass ratios'),(33,9,'Question 6: mole ratios and hydrates',4)],
 [('How do you convert mass to moles?','Use n = m/M with mass in grams and molar mass in g/mol. A mole contains Avogadro’s number of particles. Say whether the particles are atoms, molecules or formula units.'),('How do balanced equations give ratios?','Equation coefficients give mole ratios, not mass ratios. Convert known mass to moles, use the coefficient ratio, then convert the required moles to mass.'),('How do you calculate concentration?','Molar concentration is moles of solute per dm³ of solution. Convert cm³ to dm³ by dividing by 1 000. For empirical formulae, divide element mole amounts by the smallest.')],
 'n = m/M  •  c = n/V  •  N = nNₐ',[
 ('Find the concentration when 5.85 g NaCl (M = 58.5 g/mol) is dissolved to make 500 cm³ of solution.','n = 5.85/58.5 = 0.100 mol. V = 500/1 000 = 0.500 dm³. c = 0.100/0.500 = 0.200 mol/dm³.'),('For 2H₂ + O₂ → 2H₂O, what mass of water forms from 4 g H₂ with excess oxygen? Use M(H₂) = 2 and M(H₂O) = 18 g/mol.','n(H₂) = 4/2 = 2 mol. Ratio H₂:H₂O is 2:2 = 1:1, so 2 mol water forms. m = 2 × 18 = 36 g.')], 'atom')

add('life','Cells & membrane transport','Cell biology',[(29,8,'Question 1.5: cell structure',8),(29,9,'Question 1.5: selective permeability',9),(19,4,'Question 3: cell diagram')],
 [('What do the main organelles do?','The nucleus contains genetic information; mitochondria carry out most aerobic ATP production; chloroplasts carry out photosynthesis. Plant cells also have a cellulose cell wall and usually a large permanent vacuole.'),('How do diffusion and osmosis differ?','Diffusion is the net movement of particles down a concentration gradient. Osmosis is the net movement of water through a selectively permeable membrane from higher to lower water potential.'),('When does transport require energy?','Active transport moves substances against their concentration gradient using energy and transport proteins. Facilitated diffusion uses membrane proteins but moves down a gradient without direct ATP input.')],
 'Structure → function → explanation',[
 ('A plant cell is placed in pure water. Explain why it becomes turgid.','Water enters by osmosis because the outside has higher water potential. The vacuole expands and pushes the cytoplasm against the cell wall. The strong wall resists further expansion, creating turgor.'),('Why does active transport require ATP while facilitated diffusion does not?','Active transport moves particles against their concentration gradient and needs an energy supply. Facilitated diffusion moves down the gradient through proteins, so no direct ATP input is needed.')], 'cell')
add('life','Mitosis & the cell cycle','Cell biology',[(29,22,'Question 5: mitotic errors',21),(22,4,'Question 7: cell division',1),(23,6,'Question 5: cell cycle')],
 [('What happens before mitosis?','During interphase the cell grows and, in S phase, replicates DNA. Each duplicated chromosome has two sister chromatids before division. DNA replication is essential for equal genetic information.'),('What is the PMAT sequence?','Prophase: chromosomes condense. Metaphase: chromosomes line up at the equator. Anaphase: sister chromatids separate to opposite poles. Telophase: nuclei reform; cytokinesis divides the cytoplasm.'),('What is the outcome of mitosis?','In normal mitosis, two daughter cells keep the parent cell’s chromosome number and are genetically identical, apart from possible mutations. Mitosis supports growth, repair and asexual reproduction.')],
 'Interphase → Prophase → Metaphase → Anaphase → Telophase',[
 ('A body cell with 6 chromosomes divides by normal mitosis. How many daughter cells form and how many chromosomes are in each?','Two daughter cells form. Each has 6 chromosomes, the same chromosome number as the parent cell.'),('Distinguish metaphase from anaphase.','At metaphase, duplicated chromosomes align at the equator. At anaphase, sister chromatids separate at the centromeres and move to opposite poles.')], 'mitosis', 'Do not confuse DNA replication in interphase with chromosome separation in anaphase. The supplied 2022 memo has an inconsistent stage description.')
add('life','Enzymes & biological molecules','Biochemistry',[(29,11,'Question 2: lactase and lactose',11),(29,13,'Question 2.3: enzyme diagram',12),(19,12,'Question 10: enzyme action')],
 [('How does an enzyme act?','An enzyme is a biological catalyst. Its active site binds a suitable substrate, helping a reaction proceed with a lower activation energy. Products leave and the enzyme can be reused.'),('Why do temperature and pH matter?','Activity usually increases with temperature up to an optimum. Excess heat or unsuitable pH can alter the active-site shape. Denaturation reduces binding and activity; cooling is not the same as denaturing.'),('What happens as substrate increases?','At fixed enzyme concentration the reaction rate rises, then levels off as active sites become saturated. More substrate cannot increase the maximum rate unless more active enzyme is available.')],
 'Enzyme + substrate ⇌ complex → enzyme + products',[
 ('Why can a high temperature reduce the rate of an enzyme-controlled reaction?','Heat can disrupt bonds maintaining enzyme shape. The active site changes, so fewer substrates bind and fewer enzyme-substrate complexes form.'),('An enzyme reaction stops getting faster when more substrate is added. Explain.','The available active sites are occupied: the enzymes are saturated. Enzyme concentration is now limiting, so adding substrate alone does not raise the maximum rate.')], 'enzyme')
add('life','Digestion & blood-glucose control','Human biology',[(29,15,'Question 3: digestion and bile',15),(29,17,'Question 3.4: blood-glucose hormones',16),(19,6,'Question 5: digestive organs')],
 [('What are digestion and absorption?','Digestion breaks large food molecules into smaller soluble molecules. Absorption moves these molecules across the intestinal wall into blood or lymph. Most nutrient absorption occurs in the small intestine.'),('What does bile do?','The liver produces bile; the gall bladder stores and concentrates it. Bile emulsifies fats into droplets, increasing surface area for lipase. Emulsification is physical and bile is not a digestive enzyme.'),('How is blood glucose regulated?','High glucose stimulates pancreatic insulin release, increasing glucose uptake and glycogen formation. Low glucose stimulates glucagon, promoting liver glycogen breakdown and glucose release. This is negative feedback.')],
 'High glucose → insulin  •  Low glucose → glucagon',[
 ('Explain how villi improve absorption.','Villi and microvilli increase surface area. A thin epithelium shortens diffusion distance. Blood capillaries and lacteals carry absorbed nutrients away, helping maintain transport gradients.'),('Describe the response to a rise in blood glucose after a meal.','Pancreatic beta cells release insulin. Body cells increase glucose uptake and the liver and muscles store glucose as glycogen. Blood glucose falls toward its regulated range.')], 'feedback')
add('life','Photosynthesis & cellular respiration','Plant biology',[(29,7,'Question 1.4: carbon cycle and photosynthesis',7),(29,2,'Question 1.1: respiration',2)],
 [('What does photosynthesis achieve?','In chloroplasts, light energy supports the conversion of carbon dioxide and water into organic molecules, with oxygen released. Chlorophyll absorbs light. Plants build biomass from the products.'),('What does respiration achieve?','Cellular respiration transfers energy from organic molecules to ATP. Glycolysis occurs in the cytoplasm; most aerobic ATP production involves mitochondria. Plants respire as well as photosynthesise.'),('How are the processes connected?','Photosynthesis stores energy in organic molecules; respiration makes that energy available for cell work. Matter cycles between organisms and the environment, but energy flows and is eventually dissipated as heat.')],
 '6CO₂ + 6H₂O + light → C₆H₁₂O₆ + 6O₂',[
 ('Name the reactants and products in the simplified photosynthesis equation.','Reactants are carbon dioxide and water, using light energy. Products are glucose and oxygen.'),('Do plants respire at night? Explain.','Yes. Living plant cells require ATP continuously, so respiration continues day and night. Photosynthesis depends on light and does not proceed normally in darkness.')], 'cycle')
add('life','Plant transport & adaptations','Plant biology',[(29,19,'Question 4.1: leaf adaptations',19),(29,21,'Questions 4.2–4.3: transport and stomata',20)],
 [('What do xylem and phloem transport?','Xylem carries water and mineral ions mainly from roots toward leaves through mostly dead conducting cells. Phloem translocates dissolved organic substances between sources and sinks through living tissue.'),('How do stomata open?','Guard cells take up solutes, lowering their water potential. Water enters by osmosis and guard cells become turgid, opening the pore. Water loss makes them flaccid and closes it.'),('How do leaves limit water loss?','A thick waxy cuticle, reduced leaf area, hairs or sunken stomata can reduce water loss. Explain how a named feature works in the environment; a feature is not useful in every habitat.')],
 'Water enters guard cells → turgor increases → pore opens',[
 ('Give two differences between xylem and phloem.','Xylem transports water/mineral ions and its main conducting cells are dead at maturity. Phloem transports sugars/other organic solutes and its conducting tissue is living.'),('Explain why a waxy cuticle benefits a plant in a dry habitat.','The waxy layer limits evaporation from the leaf surface. This reduces water loss when water is scarce and helps the plant maintain cell turgor.')], 'flow')
add('life','Ecology, nutrient cycles & biodiversity','Ecology',[(29,18,'Question 4: nitrogen-fixing plants',18),(22,6,'Question 9: elephant ecology',2),(19,10,'Question 9: mangrove ecosystems')],
 [('How do food webs show energy flow?','Arrows point from food to consumer, showing energy transfer. Producers form the first trophic level. Energy available usually decreases at higher levels because organisms respire and not all biomass is eaten or assimilated.'),('How do nutrient cycles differ from energy flow?','Elements such as carbon and nitrogen are recycled. Decomposers break down organic material, returning nutrients to usable pools. Energy enters mainly as sunlight and leaves as heat.'),('What makes a relationship mutualistic?','In mutualism both partners benefit. Nitrogen-fixing bacteria obtain organic nutrients from plants and supply biologically usable nitrogen compounds. Biodiversity includes genetic, species and ecosystem variation.')],
 'Sun → producer → consumer → decomposer',[
 ('In grass → locust → frog → snake, identify the producer and secondary consumer.','Grass is the producer. Locust is the primary consumer and frog is the secondary consumer. Snake is the tertiary consumer.'),('Explain one effect of habitat fragmentation on biodiversity.','Fragments isolate populations and can reduce access to food, mates and migration routes. Smaller isolated populations are more vulnerable to local extinction, reducing biodiversity.')], 'cycle')
add('life','Evolution, climate & scientific essays','Earth and life',[(19,9,'Question 8: fossil sequence'),(26,2,'Paper 2: climate-change essay',1),(21,2,'Paper 2: source-based essay')],
 [('How do fossils provide evidence?','Fossils record past organisms and change over time. Relative dating orders events or layers; numerical dating estimates ages. Interpret the actual scale and labels before comparing fossils.'),('How can climate change affect biodiversity?','Changing temperatures, rainfall and habitats can shift ranges and disrupt feeding relationships. Some organisms disperse or adjust; others cannot keep pace. Distinguish evidence, uncertainty and unsupported claims.'),('How do you build a scientific argument?','State a position, use specific source evidence and explain its relevance. Discuss counterarguments fairly and conclude in proportion to the evidence. Evaluate source reliability, methods and possible bias.')],
 'Claim → source evidence → explanation → evaluation',[
 ('Explain the difference between relative and numerical fossil dating.','Relative dating places fossils or rock layers in order from older to younger without assigning an exact age. Numerical dating estimates an age in years, often using radioactive isotope decay.'),('Give one argument and one counterpoint for climate change causing species extinctions.','Argument: rapid habitat changes may exceed the ability of specialist species to move or adapt. Counterpoint: responses vary and some species can shift range, so evidence should be assessed by species and region rather than assuming all will go extinct.')], 'timeline')
add('life','Scientific investigations & practical skills','Practical science',[(20,4,'Practical: hypotheses and variables'),(25,2,'2023 practical: biological food tests'),(22,7,'Question 9.6: population data',3)],
 [('How do you distinguish variables?','The independent variable is deliberately changed; the dependent variable is measured; controlled variables are held constant. A fair comparison changes one tested factor at a time.'),('What makes a useful hypothesis?','State a testable predicted relationship, ideally with a biological reason. A conclusion must answer the aim using recorded evidence, rather than simply repeating the hypothesis.'),('How do you improve reliability and validity?','Repeat measurements and calculate appropriate summaries to improve reliability. Control confounding factors, use suitable equipment and a comparison/control where appropriate to support validity.')],
 'Aim → hypothesis → variables → method → results → conclusion',[
 ('A learner tests how temperature affects amylase activity. Name the independent, dependent and two controlled variables.','Independent: temperature. Dependent: reaction rate or time to a defined endpoint. Controls: pH and enzyme concentration (also substrate concentration/volume where appropriate).'),('Three repeat reaction times are 40 s, 42 s and 38 s. Calculate the mean and explain why repeats help.','Mean = (40 + 42 + 38)/3 = 40 s. Repeats help reveal random variation and anomalous results, making the estimate of typical performance more reliable.')], 'bars')

add('sports','Bones, muscles & movement','Anatomy',[(43,3,'Question 2: weightlifting and anatomy',4)],
 [('What does the skeleton do?','The skeleton supports and protects the body, provides muscle attachment sites and acts as a lever system. Bones store minerals such as calcium and phosphorus; marrow produces blood cells.'),('How do antagonistic muscles work?','Muscles generate pulling forces. For a particular movement the agonist produces the main action and the antagonist opposes or controls it. Their roles change when movement reverses.'),('What are contraction types?','Isometric contraction develops tension with no overall muscle-length change. Concentric contraction shortens an active muscle; eccentric contraction lengthens an active muscle while controlling a load.')],
 'Muscle force → tendon → bone → joint movement',[
 ('During a controlled biceps curl upwards, identify the main agonist and contraction type.','The biceps brachii is a main elbow-flexion agonist and contracts concentrically as it shortens. The triceps acts as an antagonist.'),('A learner holds a squat still. Name the contraction type and explain it.','The muscles maintaining the position act mainly isometrically. They produce tension without a visible change in overall muscle length or joint position.')], 'lever')
add('sports','Energy systems & exercise','Exercise physiology',[(43,6,'Question 3: energy-system source',8)],
 [('How does the ATP-PC system work?','Stored ATP and phosphocreatine provide very rapid energy for brief maximal efforts. Capacity is limited, and recovery between efforts helps replenish phosphocreatine stores.'),('How do glycolytic and aerobic systems differ?','Anaerobic glycolysis supplies ATP rapidly from carbohydrate without direct oxygen use. Aerobic metabolism uses oxygen and can sustain ATP production from carbohydrate and fat over longer periods.'),('Do the systems switch on separately?','All energy systems contribute together. Their relative contribution changes with intensity, duration and training. Use sporting examples to justify the dominant contribution rather than claiming exclusive use.')],
 'Short explosive ↔ sustained moderate effort',[
 ('Which energy system has a major role in a single maximal 5-second sprint, and why?','The ATP-PC system has a major role because it supplies ATP very quickly for a brief maximal effort. Other systems also contribute.'),('Why is aerobic fitness useful in a match containing repeated sprints?','Aerobic metabolism supports activity between sprints and recovery, including phosphocreatine restoration. It helps the athlete sustain repeated efforts across the match.')], 'energy')
add('sports','Levers & anatomical planes','Biomechanics',[(43,9,'Question 4: lever systems',11),(43,12,'Question 4.5: anatomical planes',14)],
 [('What are the parts of a lever?','A lever is a rigid structure rotating around a fulcrum. Effort is the applied force and load is the resistance. The effort and load arms are perpendicular moment-arm distances from the pivot to force lines.'),('How are lever classes organised?','First class has the fulcrum in the middle; second class has the load in the middle; third class has effort in the middle. Third-class levers often favour speed and range over force advantage.'),('Which movements occur in each plane?','Sagittal: flexion and extension. Frontal: abduction and adduction. Transverse: rotation. Name the joint and movement, and distinguish the movement plane from the axis perpendicular to it.')],
 'Torque = force × perpendicular moment arm',[
 ('In a lever, effort lies between the fulcrum and the load. Name the class and give a body example.','It is a third-class lever. In elbow flexion, the elbow is the fulcrum, the biceps applies effort near the elbow and the load is farther along the forearm/hand.'),('A 30 N force acts at a perpendicular distance of 0.2 m from a pivot. Find the torque.','Torque = 30 × 0.2 = 6 N·m. The perpendicular distance to the force line, rather than any arbitrary bone length, must be used.')], 'lever')
add('sports','Nutrition & exercise fuel','Sports nutrition',[(43,13,'Question 5: diet source evaluation',15)],
 [('What do macronutrients supply?','Carbohydrate and protein each supply about 4 kcal/g; fat supplies about 9 kcal/g. Carbohydrate is an important exercise fuel; protein supports growth and repair; fat also supports membranes, insulation and vitamin absorption.'),('What does glycaemic index compare?','GI compares the blood-glucose response to equal amounts of available carbohydrate from different foods. It is affected by food processing and meal context. A carbohydrate-free food is not meaningfully assigned a low GI.'),('How should you evaluate a diet claim?','Ask what evidence supports it, whether the study population matches the claim and whether a source is selling something. School questions about a diet are an opportunity to evaluate evidence, not a personal meal prescription.')],
 'Energy ≈ 4 × carbohydrate g + 4 × protein g + 9 × fat g',[
 ('A snack contains 20 g carbohydrate, 5 g protein and 4 g fat. Estimate energy in kcal.','Energy = 20 × 4 + 5 × 4 + 4 × 9 = 80 + 20 + 36 = 136 kcal.'),('Why is it misleading to describe a carbohydrate-free food as low GI?','GI is measured using a portion containing a standard amount of available carbohydrate. A food with essentially none cannot be compared on that basis, so its GI is generally not applicable.')], 'bars', 'Use these as exam concepts. One nutritional calorie (kcal) is 1 000 small calories; the supplied memo uses the word calorie loosely.')
add('sports','Heart, lungs & aerobic fitness','Exercise physiology',[(43,16,'Question 6: VO₂ max and circulation',18)],
 [('What is cardiac output?','Cardiac output is the volume pumped by a ventricle per minute. It equals heart rate multiplied by stroke volume. Keep mL and L consistent when calculating.'),('What is VO₂ max?','VO₂ max is the maximum rate of oxygen consumption during intense exercise, often expressed as mL/kg/min. It reflects the integrated ability to deliver and use oxygen, not simply lung size.'),('How does training affect endurance?','Endurance training can increase stroke volume, capillary density and mitochondrial capacity, and lower resting heart rate. Adaptations depend on the training programme and the individual.')],
 'Cardiac output = heart rate × stroke volume',[
 ('Heart rate is 150 beats/min and stroke volume is 120 mL/beat. Find cardiac output in L/min.','Q = 150 × 120 = 18 000 mL/min. Divide by 1 000: Q = 18 L/min.'),('Why do thin alveolar walls and many surrounding capillaries support gas exchange?','Thin walls reduce diffusion distance. The capillary network supplies a large exchange area and helps maintain oxygen and carbon-dioxide concentration gradients.')], 'heart')
add('sports','Arousal, psychology & motor skills','Sports psychology',[(43,20,'Question 7: arousal and performance',21)],
 [('What is the inverted-U model?','Performance may improve as arousal rises toward an optimum and then fall as arousal becomes excessive. The optimum varies with the task, skill level and individual; it is a model rather than a universal law.'),('How do skill demands differ?','Fine skills require precise small-muscle control; gross skills use larger muscle groups. Complex tasks often need greater attentional control. Do not assume every athlete has the same optimum arousal.'),('How can an athlete regulate arousal?','Breathing routines, imagery and attention cues can help manage arousal. Match a strategy to the athlete and task, and explain how it could support concentration or readiness.')],
 'Low arousal → optimum zone → excessive arousal',[
 ('Use the inverted-U model to explain why too much arousal can hurt a precision task.','Arousal above the athlete’s optimum can increase tension and disrupt attention and fine control. This may reduce accuracy in a precision task such as putting.'),('Give two ways an athlete could reduce excessive pre-match arousal.','Controlled breathing can help regulate physiological activation. A familiar attention routine or calming imagery can redirect focus toward useful task cues.')], 'arousal')
add('sports','Training adaptations & evidence-based essays','Performance',[(43,5,'Question 2.7: musculoskeletal adaptations',6),(43,23,'Question 8: limits of human performance',23)],
 [('How do training principles guide progress?','Specificity means adaptations match the training demand. Progressive overload gradually increases that demand. Recovery allows adaptation; excessive load without recovery can impair performance.'),('Which adaptations are relevant?','Resistance training can increase strength and muscle size; endurance training can increase aerobic capacity and fatigue resistance. Separate immediate exercise responses from adaptations developed over weeks or months.'),('How do you evaluate performance limits?','Use evidence about physiology, training, technology and participation. Consider both biological constraints and changes that allow progress. Distinguish fair technological improvements from prohibited practices without assuming a source is neutral.')],
 'Training stimulus + recovery → adaptation',[
 ('Distinguish an acute response to running from a long-term endurance adaptation.','A raised heart rate during a run is an acute response. An increased stroke volume after months of appropriate endurance training is a chronic adaptation.'),('Give one supported argument on each side of whether athletic records can continue improving.','For improvement: better training methods, technology and wider participation can improve performance. For limits: human physiology places constraints on oxygen delivery, force production and recovery. A conclusion should weigh the evidence for the specific sport.')], 'growth')
